def countAndZeroTriples(nums):
    B = 12
    FULL = (1 << B) - 1
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    sub = [0] * (1 << B)
    items = list(cnt.items())
    for x, cx in items:
        for y, cy in items:
            sub[x & y] += cx * cy
    for b in range(B):
        bit = 1 << b
        for m in range(1 << B):
            if m & bit:
                sub[m] += sub[m ^ bit]
    ans = 0
    for v, c in items:
        ans += c * sub[FULL & ~v]
    return ans
